WITH flattened AS (SELECT id, customer_id, coupon_codes, k, attr_value FROM carts LATERAL VIEW EXPLODE(attributes) e AS k, attr_value) SELECT s.id, s.customer_id, s.k, s.attr_value, (SELECT MIN(a2.balance) FROM accounts a2 WHERE a2.customer_id = s.customer_id) AS min_account_balance FROM flattened s ORDER BY k DESC NULLS FIRST;
